const http = this.helpers.httpRequest;

// ⚙️ CONFIG
const SUPABASE_URL = 'https://zavabpchdvssvdnwtuyu.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InphdmFicGNoZHZzc3Zkbnd0dXl1Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODQzNDA4NDgsImV4cCI6MjA5OTkxNjg0OH0.bGIex-jior3Q48OAwXRmuwJbt6SZ_MQMiyiieY4WDm4';
const supabaseHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

// 📡 Fetch subscribers from Supabase
async function getSubscribers(product) {
  const url = SUPABASE_URL + '/rest/v1/alert_subscribers?product=eq.' + product + '&active=eq.true&select=phone,plan,config';
  try {
    const data = await http({ method: 'GET', url, headers: supabaseHeaders });
    return Array.isArray(data) ? data : [];
  } catch (e) {
    // Fallback: empty list if table doesn't exist yet
    return [];
  }
}

// 📤 Send WhatsApp message
async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}

// 1. Fetch metals prices from currency-api (free CDN, no key)
const url = 'https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/usd.min.json';
const data = await http({ method: 'GET', url: url });

const xau = data.usd['xau'];
const xag = data.usd['xag'];
const xpt = data.usd['xpt'];
const xpd = data.usd['xpd'];
const metals = { xau, xag, xpt, xpd };
for (const [k, v] of Object.entries(metals)) {
  if (v) metals[k] = (1 / v).toFixed(2);
}

const date = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

const text = '🥇 *Precious Metals — ' + date + '*\n\n' +
  '🟡 *Gold:* $' + metals.xau + '/oz\n' +
  '⚪ *Silver:* $' + metals.xag + '/oz\n' +
  '🔘 *Platinum:* $' + metals.xpt + '/oz\n' +
  '⚫ *Palladium:* $' + metals.xpd + '/oz\n\n' +
  '⚡ *GoldTrack*';

// 2. Send to all subscribers
const subscribers = await getSubscribers('goldtrack');
if (subscribers.length === 0) {
  return { sent: 0, message: 'No active subscribers' };
}

const results = [];
for (const sub of subscribers) {
  try {
    await sendMsg(sub.phone, text);
    results.push({ phone: sub.phone, status: 'sent' });
  } catch (e) {
    results.push({ phone: sub.phone, status: 'error', error: e.message });
  }
}

return { sent: results.filter(r => r.status === 'sent').length, total: subscribers.length };
